// ==UserScript==
// @name         GreasyFork - Auto-Publisher Bridge
// @name:ru      GreasyFork - Авто-публикатор скриптов
// @namespace    https://greasyfork.org/users/1522624-basimovif-ai
// @version      2.0.0
// @description  Automates script publishing, updating, and rich description filling on GreasyFork with zero manual steps.
// @description:ru Полная автоматизация публикации, обновления и оформления Markdown описаний скриптов на GreasyFork без ручных действий.
// @author       basimovif-ai
// @license      MIT
// @homepageURL  https://github.com/BasimovIF-AI/steamgifts-userscripts
// @supportURL   https://github.com/BasimovIF-AI/steamgifts-userscripts/issues
// @match        https://greasyfork.org/*/script_versions/new*
// @match        https://greasyfork.org/*/scripts/*/versions/new*
// @match        https://greasyfork.org/*/scripts/*/admin*
// @match        https://greasyfork.org/*/scripts/*
// @grant        unsafeWindow
// @run-at       document-idle
// ==/UserScript==

(function() {
    'use strict';

    // 0. Авто-переход в /admin после публикации нового скрипта
    const pendingDesc = sessionStorage.getItem('gf_pending_desc');
    if (pendingDesc && window.location.pathname.match(/\/scripts\/\d+-[^\/]+$/)) {
        sessionStorage.removeItem('gf_pending_desc');
        window.location.href = window.location.pathname + '/admin?auto_desc=' + encodeURIComponent(pendingDesc);
        return;
    }

    const params = new URLSearchParams(window.location.search);
    const publishFile = params.get('auto_publish');
    const updateFile = params.get('auto_update');
    const editDescFile = params.get('auto_desc');

    const fileName = publishFile || updateFile || editDescFile;
    if (!fileName) {
        return;
    }

    const embeddedCodes = {"steamgifts-chance-per-point.user.js":"// ==UserScript==\n// @name         SteamGifts - Chance Per Point (‱)\n// @name:ru      SteamGifts - Шанс на очко (‱)\n// @namespace    https://greasyfork.org/users/1522624-basimovif-ai\n// @version      7.0.0\n// @description  Adds a win chance per point column in basis points (‱) and enables hiding giveaways above a chosen threshold on SteamGifts entered page.\n// @description:ru Добавляет столбец с шансом на победу на одно очко в базисных пунктах (‱) и позволяет скрывать раздачи с шансом выше заданного значения.\n// @author       basimovif-ai\n// @license      MIT\n// @homepageURL  https://github.com/BasimovIF-AI/steamgifts-userscripts\n// @supportURL   https://github.com/BasimovIF-AI/steamgifts-userscripts/issues\n// @match        https://www.steamgifts.com/giveaways/entered*\n// @grant        GM_addStyle\n// @run-at       document-end\n// ==/UserScript==\n\n(function() {\n    'use strict';\n\n    const isRu = (navigator.language || '').toLowerCase().startsWith('ru');\n    const i18n = {\n        filterLabel: isRu ? 'Фильтр по шансу: скрыть всё, что выше' : 'Win Chance Filter: hide entries above',\n        filterBtn: isRu ? 'Фильтровать' : 'Filter',\n        resetBtn: isRu ? 'Сбросить' : 'Reset',\n        colHeader: isRu ? 'Шанс/Очко (‱)' : 'Chance/Pt (‱)',\n        colHeaderTitle: isRu\n            ? 'Шанс на победу за одно очко ((Копии / (Участники * Очки)) * 10000‱)'\n            : 'Win chance per single point ((Copies / (Entries * Points)) * 10000‱)',\n        errorText: isRu ? 'Ошибка' : 'Error',\n    };\n\n    // Стили для панели управления\n    GM_addStyle(`\n        .sg-chance-filter-panel {\n            background-color: #f0f2f5;\n            padding: 10px;\n            margin-bottom: 15px;\n            border-radius: 5px;\n            display: flex;\n            align-items: center;\n            gap: 10px;\n        }\n        .sg-chance-filter-panel input {\n            border: 1px solid #ccc;\n            padding: 5px;\n            border-radius: 3px;\n            width: 80px;\n        }\n        .sg-chance-filter-panel button {\n            background-color: #4CAF50;\n            color: white;\n            border: none;\n            padding: 6px 12px;\n            text-align: center;\n            text-decoration: none;\n            display: inline-block;\n            font-size: 14px;\n            cursor: pointer;\n            border-radius: 3px;\n        }\n        .sg-chance-filter-panel button.reset {\n            background-color: #f44336;\n        }\n    `);\n\n    // --- ФУНКЦИИ ФИЛЬТРАЦИИ ---\n\n    function applyFilter() {\n        const filterValueInput = document.getElementById('chance-filter-input');\n        if (!filterValueInput) return;\n\n        // Получаем значение (максимальный порог) и конвертируем его из ‱ в чистое число\n        const maxPerMyriad = parseFloat(filterValueInput.value);\n        if (isNaN(maxPerMyriad)) {\n            resetFilter();\n            return;\n        }\n        const maxChance = maxPerMyriad / 10000.0; // Делим на 10000\n\n        const allRows = document.querySelectorAll('.table__row-outer-wrap');\n        allRows.forEach(rowWrapper => {\n            const innerRow = rowWrapper.querySelector('.table__row-inner-wrap');\n            const rowChance = parseFloat(innerRow.dataset.chancePerPoint);\n\n            if (!isNaN(rowChance) && rowChance > maxChance) {\n                rowWrapper.style.display = 'none';\n            } else {\n                rowWrapper.style.display = '';\n            }\n        });\n    }\n\n    function resetFilter() {\n        const filterValueInput = document.getElementById('chance-filter-input');\n        if (filterValueInput) filterValueInput.value = '';\n\n        const allRows = document.querySelectorAll('.table__row-outer-wrap');\n        allRows.forEach(rowWrapper => {\n            rowWrapper.style.display = '';\n        });\n    }\n\n    // --- ОСНОВНАЯ ЛОГИКА ---\n    function createFilterPanel() {\n        if (document.getElementById('chance-filter-panel')) return;\n\n        const container = document.querySelector('.table');\n        if (!container) return;\n\n        const panel = document.createElement('div');\n        panel.id = 'chance-filter-panel';\n        panel.className = 'sg-chance-filter-panel';\n        panel.innerHTML = `\n            <label for=\"chance-filter-input\"><b>${i18n.filterLabel}</b></label>\n            <input type=\"number\" id=\"chance-filter-input\" placeholder=\"1.00\" step=\"0.01\">\n            <span>‱</span>\n            <button id=\"apply-chance-filter\">${i18n.filterBtn}</button>\n            <button id=\"reset-chance-filter\" class=\"reset\">${i18n.resetBtn}</button>\n        `;\n\n        container.parentNode.insertBefore(panel, container);\n\n        document.getElementById('apply-chance-filter').addEventListener('click', applyFilter);\n        document.getElementById('reset-chance-filter').addEventListener('click', resetFilter);\n    }\n\n    function processGiveaways() {\n        const header = document.querySelector('.table__heading');\n        const giveaways = document.querySelectorAll('.table__row-inner-wrap:not(.chance-processed)');\n\n        if (!header || giveaways.length === 0) {\n            return;\n        }\n\n        if (!header.querySelector('.chance-per-point-header')) {\n            const newHeaderCell = document.createElement('div');\n            newHeaderCell.className = 'table__column--width-small text-center chance-per-point-header';\n            newHeaderCell.textContent = i18n.colHeader;\n            newHeaderCell.title = i18n.colHeaderTitle;\n            header.appendChild(newHeaderCell);\n\n            const allRowsForGrid = document.querySelectorAll('.table__heading, .table__row-inner-wrap');\n            allRowsForGrid.forEach(row => {\n                if(!row.style.gridTemplateColumns.endsWith('110px')) {\n                    const currentGridStyle = window.getComputedStyle(row).gridTemplateColumns;\n                    row.style.gridTemplateColumns = currentGridStyle + ' 110px';\n                }\n            });\n        }\n\n        giveaways.forEach(row => {\n            try {\n                const titleElement = row.querySelector('a.table__column__heading');\n                if (!titleElement) {\n                    row.classList.add('chance-processed');\n                    return;\n                }\n                const titleText = titleElement.textContent;\n\n                const pointsMatch = titleText.match(/\\((\\d+)P\\)/);\n                const points = pointsMatch ? parseInt(pointsMatch[1], 10) : NaN;\n\n                const copiesMatch = titleText.match(/\\((\\d+)\\sCopies\\)/);\n                const copies = copiesMatch ? parseInt(copiesMatch[1], 10) : 1;\n\n                let entries = NaN;\n                const columns = row.querySelectorAll('.table__row-inner-wrap > div.table__column--width-small');\n                for (const col of columns) {\n                    if (/^[\\d,]+$/.test(col.textContent.trim())) {\n                         entries = parseInt(col.textContent.trim().replace(/,/g, ''), 10);\n                         break;\n                    }\n                }\n\n                let chanceText = 'N/A';\n                let rawChance = 0;\n\n                if (!isNaN(entries) && entries > 0 && !isNaN(points) && points > 0 && copies > 0) {\n                    const chance = copies / (entries * points);\n                    rawChance = chance;\n                    chanceText = (chance * 10000).toFixed(2) + '‱';\n                }\n\n                row.dataset.chancePerPoint = rawChance;\n\n                const newCell = document.createElement('div');\n                newCell.className = 'table__column--width-small text-center';\n                newCell.textContent = chanceText;\n                row.appendChild(newCell);\n\n            } catch (e) {\n                console.error('SteamGifts Chance Per Point: error processing row:', row, e);\n                row.dataset.chancePerPoint = 0;\n                const errorCell = document.createElement('div');\n                errorCell.className = 'table__column--width-small text-center';\n                errorCell.textContent = i18n.errorText;\n                row.appendChild(errorCell);\n            } finally {\n                row.classList.add('chance-processed');\n            }\n        });\n    }\n\n    // --- ИНИЦИАЛИЗАЦИЯ И НАБЛЮДЕНИЕ ЗА ИЗМЕНЕНИЯМИ ---\n    const observer = new MutationObserver((mutationsList) => {\n        for(const mutation of mutationsList) {\n            if (mutation.addedNodes.length > 0) {\n                 const hasNewRows = Array.from(mutation.addedNodes).some(node => node.nodeType === 1 && node.classList.contains('table__row-outer-wrap'));\n                 if(hasNewRows){\n                    setTimeout(() => {\n                        processGiveaways();\n                        if (document.getElementById('chance-filter-input').value) {\n                            applyFilter();\n                        }\n                    }, 200);\n                    return;\n                }\n            }\n        }\n    });\n\n    const targetNode = document.querySelector('.table');\n    if (targetNode) {\n        observer.observe(targetNode, { childList: true, subtree: true });\n    }\n\n    setTimeout(() => {\n        createFilterPanel();\n        processGiveaways();\n    }, 500);\n\n})();\n","steamgifts-group-stats-checker.user.js":"// ==UserScript==\n// @name         SteamGifts - Group Stats Checker (Universal)\n// @name:ru      SteamGifts - Проверка статистики в группах (Универсальный)\n// @namespace    https://greasyfork.org/users/1522624-basimovif-ai\n// @version      1.7.0\n// @description  Displays interactive group stat buttons on giveaway pages and autofills thank-you comments for giveaway creator.\n// @description:ru Отображает кнопки статистики групп на страницах раздач и автоматически заполняет благодарность создателю раздачи.\n// @author       basimovif-ai\n// @license      MIT\n// @homepageURL  https://github.com/BasimovIF-AI/steamgifts-userscripts\n// @supportURL   https://github.com/BasimovIF-AI/steamgifts-userscripts/issues\n// @match        https://www.steamgifts.com/giveaway/*\n// @grant        none\n// ==/UserScript==\n\n(function() {\n    'use strict';\n\n    const isRu = (navigator.language || '').toLowerCase().startsWith('ru');\n    const i18n = {\n        btnTitle: (groupName) => isRu ? `Проверить мою статистику в группе: ${groupName}` : `Check my stats in group: ${groupName}`,\n        formulaTitle: isRu ? 'Нажмите для формулы расчета' : 'Click to toggle calculation formula',\n        notFound: isRu ? '(не найден)' : '(not found)',\n        error: isRu ? 'Ошибка' : 'Error',\n        networkError: isRu ? 'Ошибка сети при запросе к группе' : 'Network error fetching group stats',\n    };\n\n    // Проверяем, что находимся на главной странице раздачи (исключаем подразделы)\n    const pathParts = window.location.pathname.split('/').filter(Boolean);\n    if (pathParts.length !== 2 && !(pathParts.length === 3 && pathParts[0] === 'giveaway')) {\n        // Поддерживает и /giveaway/:id/:slug, и стандартный формат\n        if (pathParts[0] !== 'giveaway') return;\n        if (pathParts.length > 3) return; // Исключаем /winners, /entries и т.д.\n    }\n\n    const origin = window.location.origin;\n\n    // Вспомогательные функции парсинга\n    const parseSentRec = (text) => {\n        const cleaned = text.replace(/,/g, '');\n        const m = cleaned.match(/([\\d.]+)\\s*\\(\\$([\\d.]+)\\)/);\n        return m ? [parseFloat(m[1]), parseFloat(m[2])] : [0, 0];\n    };\n\n    const parseDiff = (text) => {\n        return parseFloat(text.replace(/[^0-9.-]/g, ''));\n    };\n\n    // Кэш для общего количества побед текущего пользователя\n    let cachedGiftsWon = null;\n\n    async function fetchGiftsWon(username) {\n        if (cachedGiftsWon !== null) return cachedGiftsWon;\n        try {\n            const r = await fetch(`${origin}/user/${username}`);\n            if (!r.ok) return 0;\n            const html = await r.text();\n            const parser = new DOMParser();\n            const doc = parser.parseFromString(html, 'text/html');\n            const profileRows = doc.querySelectorAll('.featured__table__row');\n            for (const pRow of profileRows) {\n                const left = pRow.querySelector('.featured__table__row__left');\n                if (left && left.textContent.trim() === 'Gifts Won') {\n                    const right = pRow.querySelector('.featured__table__row__right a');\n                    if (right) {\n                        cachedGiftsWon = parseInt(right.textContent.replace(/,/g, ''), 10);\n                        return cachedGiftsWon;\n                    }\n                }\n            }\n        } catch (e) {\n            console.error('SteamGifts Group Stats: error fetching Gifts Won:', e);\n        }\n        return 0;\n    }\n\n    // Запрос статистики пользователя внутри конкретной группы\n    async function fetchGroupStats(groupPath, username) {\n        const groupSearchUrl = `${origin}${groupPath}/users/search?q=${encodeURIComponent(username)}`;\n        const r = await fetch(groupSearchUrl);\n        if (!r.ok) throw new Error(i18n.networkError);\n        const html = await r.text();\n        const parser = new DOMParser();\n        const doc = parser.parseFromString(html, 'text/html');\n        const memberRows = doc.querySelectorAll('.table__rows .table__row-outer-wrap');\n\n        for (const memberRow of memberRows) {\n            const nameEl = memberRow.querySelector('.table__column__heading');\n            if (nameEl && nameEl.textContent.trim().toLowerCase() === username.toLowerCase()) {\n                const cols = memberRow.querySelectorAll('.table__column--width-small.text-center');\n                if (cols.length >= 4) {\n                    return {\n                        sentText: cols[0].textContent.trim(),\n                        recText: cols[1].textContent.trim(),\n                        siteGiftDiffStr: cols[2].textContent.trim(),\n                        siteValueDiffStr: cols[3].textContent.trim()\n                    };\n                }\n            }\n        }\n        return null; // Пользователь не найден в группе\n    }\n\n    async function init() {\n        // 1. Поиск имени текущего пользователя на странице\n        const avatarEl = document.querySelector('a.nav__avatar-outer-wrap[href^=\"/user/\"]');\n        if (!avatarEl) return;\n        const username = avatarEl.getAttribute('href').replace('/user/', '');\n\n        // 2. Поиск создателя раздачи\n        const creatorLink = document.querySelector('.featured__columns a[href^=\"/user/\"]:not(.featured_giveaway_image_avatar)');\n        const creatorName = creatorLink ? creatorLink.textContent.trim() : null;\n\n        // 3. Автозаполнение комментария, если поле присутствует и оно пустое\n        if (creatorName) {\n            const commentTextarea = document.querySelector('textarea[name=\"description\"]');\n            if (commentTextarea && commentTextarea.value.trim() === \"\") {\n                commentTextarea.value = `Thanks a lot ${creatorName}!`;\n            }\n        }\n\n        // 4. Поиск ссылки на страницу со списком групп раздачи\n        const groupLinkEl = document.querySelector('a.featured__column--group');\n        if (!groupLinkEl) return;\n\n        const groupsPageUrl = origin + groupLinkEl.getAttribute('href');\n\n        // Создаем контейнер для кнопок рядом с индикатором групп\n        const container = document.createElement('span');\n        container.className = 'sg-group-stats-wrapper';\n        container.style.marginLeft = '10px';\n        container.style.display = 'inline-flex';\n        container.style.gap = '6px';\n        container.style.alignItems = 'center';\n        groupLinkEl.parentNode.insertBefore(container, groupLinkEl.nextSibling);\n\n        try {\n            // Загружаем вспомогательную страницу со списком групп раздачи\n            const r = await fetch(groupsPageUrl);\n            if (!r.ok) return;\n            const html = await r.text();\n            const parser = new DOMParser();\n            const doc = parser.parseFromString(html, 'text/html');\n\n            // Находим все текстовые ссылки на группы (они ведут на /group/...)\n            const groupLinks = doc.querySelectorAll('.table__rows a.table__column__heading[href^=\"/group/\"]');\n\n            const groups = [];\n            groupLinks.forEach(el => {\n                const href = el.getAttribute('href');\n                const name = el.textContent.trim();\n                if (href && name) {\n                    groups.push({ name, path: href });\n                }\n            });\n\n            // Для каждой обнаруженной группы создаем интерактивную кнопку\n            groups.forEach(group => {\n                const btn = document.createElement('button');\n                btn.style.background = '#4b5668';\n                btn.style.color = '#d2d6da';\n                btn.style.border = 'none';\n                btn.style.padding = '2px 6px';\n                btn.style.borderRadius = '3px';\n                btn.style.fontSize = '11px';\n                btn.style.cursor = 'pointer';\n                btn.style.display = 'inline-flex';\n                btn.style.alignItems = 'center';\n                btn.style.gap = '4px';\n                btn.style.fontFamily = 'inherit';\n                btn.style.transition = 'background 0.2s';\n                btn.title = i18n.btnTitle(group.name);\n                btn.innerHTML = `<i class=\"fa fa-bar-chart\"></i> ${group.name}`;\n\n                btn.addEventListener('mouseenter', () => btn.style.background = '#5a687c');\n                btn.addEventListener('mouseleave', () => btn.style.background = '#4b5668');\n\n                btn.addEventListener('click', async (e) => {\n                    e.preventDefault();\n                    btn.disabled = true;\n                    btn.innerHTML = `<i class=\"fa fa-refresh fa-spin\"></i> ${group.name}`;\n\n                    try {\n                        const [userData, giftsWon] = await Promise.all([\n                            fetchGroupStats(group.path, username),\n                            fetchGiftsWon(username)\n                        ]);\n\n                        const resultContainer = document.createElement('span');\n                        resultContainer.style.fontSize = '12px';\n                        resultContainer.style.display = 'inline-flex';\n                        resultContainer.style.alignItems = 'center';\n                        resultContainer.style.gap = '4px';\n\n                        const label = document.createElement('span');\n                        label.textContent = `${group.name}:`;\n                        label.style.fontWeight = 'bold';\n                        label.style.color = '#7f8c8d';\n                        resultContainer.appendChild(label);\n\n                        if (userData) {\n                            // Расчет и отрисовка интерактивной статистики\n                            const [sentCount, sentValue] = parseSentRec(userData.sentText);\n                            const [recCount, recValue] = parseSentRec(userData.recText);\n                            const siteGiftDiff = parseDiff(userData.siteGiftDiffStr);\n                            const siteValueDiff = parseDiff(userData.siteValueDiffStr);\n\n                            const calculatedGiftDiff = sentCount - recCount;\n                            const calculatedValueDiff = sentValue - recValue;\n\n                            const isGiftMatch = Math.abs(calculatedGiftDiff - siteGiftDiff) < 0.05;\n                            const isValueMatch = Math.abs(calculatedValueDiff - siteValueDiff) < 0.05;\n\n                            const giftColor = isGiftMatch ? '#2e7d32' : '#c62828';\n                            const valueColor = isValueMatch ? '#2e7d32' : '#c62828';\n\n                            const statsSpan = document.createElement('span');\n                            statsSpan.style.cursor = 'pointer';\n                            statsSpan.style.fontWeight = 'bold';\n                            statsSpan.style.userSelect = 'none';\n                            statsSpan.style.color = '#7f8c8d';\n                            statsSpan.style.transition = 'opacity 0.15s ease';\n                            statsSpan.title = i18n.formulaTitle;\n\n                            const renderStats = (expanded) => {\n                                statsSpan.innerHTML = '';\n                                statsSpan.appendChild(document.createTextNode('('));\n\n                                if (expanded) {\n                                    const formula = document.createElement('span');\n                                    formula.textContent = `${sentCount}-${recCount}=`;\n                                    statsSpan.appendChild(formula);\n                                }\n                                const giftResult = document.createElement('span');\n                                giftResult.textContent = userData.siteGiftDiffStr;\n                                giftResult.style.color = giftColor;\n                                statsSpan.appendChild(giftResult);\n\n                                statsSpan.appendChild(document.createTextNode('; '));\n\n                                if (expanded) {\n                                    const formula = document.createElement('span');\n                                    formula.textContent = `$${sentValue}-$${recValue}=`;\n                                    statsSpan.appendChild(formula);\n                                }\n                                const valueResult = document.createElement('span');\n                                valueResult.textContent = userData.siteValueDiffStr;\n                                valueResult.style.color = valueColor;\n                                statsSpan.appendChild(valueResult);\n\n                                statsSpan.appendChild(document.createTextNode(')'));\n\n                                if (expanded) {\n                                    const winsSpan = document.createElement('span');\n                                    winsSpan.textContent = ` ${giftsWon}`;\n                                    statsSpan.appendChild(winsSpan);\n                                }\n                            };\n\n                            let isExpanded = false;\n                            renderStats(isExpanded);\n\n                            statsSpan.addEventListener('mouseenter', () => { statsSpan.style.opacity = '0.7'; });\n                            statsSpan.addEventListener('mouseleave', () => { statsSpan.style.opacity = '1'; });\n                            statsSpan.addEventListener('click', (ev) => {\n                                ev.preventDefault();\n                                isExpanded = !isExpanded;\n                                renderStats(isExpanded);\n                            });\n\n                            resultContainer.appendChild(statsSpan);\n                        } else {\n                            const notMember = document.createElement('span');\n                            notMember.textContent = i18n.notFound;\n                            notMember.style.color = '#7f8c8d';\n                            notMember.style.fontStyle = 'italic';\n                            resultContainer.appendChild(notMember);\n                        }\n\n                        btn.replaceWith(resultContainer);\n                    } catch (err) {\n                        console.error('SteamGifts Group Stats error:', err);\n                        btn.disabled = false;\n                        btn.innerHTML = `<i class=\"fa fa-exclamation-triangle\"></i> ${i18n.error}`;\n                    }\n                });\n\n                container.appendChild(btn);\n            });\n\n        } catch (e) {\n            console.error('SteamGifts Group Stats: failed to load giveaway groups:', e);\n        }\n    }\n\n    init();\n})();\n","steamgifts-region-auto-selector.user.js":"// ==UserScript==\n// @name         SteamGifts - Region Auto-Selector via SteamDB Tab\n// @name:ru      SteamGifts - Автовыбор регионов через SteamDB\n// @namespace    https://greasyfork.org/users/1522624-basimovif-ai\n// @version      1.5.0\n// @description  Bypasses Cloudflare by opening SteamDB in a temporary tab and auto-selects restricted countries when creating SteamGifts giveaways.\n// @description:ru Обходит Cloudflare открытием временной вкладки SteamDB и автоматически отмечает региональные ограничения при создании раздачи на SteamGifts.\n// @author       basimovif-ai\n// @license      MIT\n// @homepageURL  https://github.com/BasimovIF-AI/steamgifts-userscripts\n// @supportURL   https://github.com/BasimovIF-AI/steamgifts-userscripts/issues\n// @match        https://www.steamgifts.com/giveaways/new\n// @match        https://steamdb.info/sub/*\n// @grant        GM_setValue\n// @grant        GM_getValue\n// @grant        window.close\n// ==/UserScript==\n\n(function() {\n    'use strict';\n\n    const isRu = (navigator.language || '').toLowerCase().startsWith('ru');\n    const i18n = {\n        subIdLabel: 'SteamDB SubID:',\n        placeholder: isRu ? 'например, 828967' : 'e.g. 828967',\n        applyBtn: isRu ? 'Применить' : 'Apply',\n        enterValidSubId: isRu ? 'Введите корректный числовой SubID' : 'Please enter a valid numeric SubID',\n        openingTab: isRu ? 'Открытие вкладки SteamDB...' : 'Opening SteamDB tab...',\n        popupBlocked: isRu ? 'Браузер заблокировал открытие вкладки. Пожалуйста, разрешите всплывающие окна.' : 'Browser blocked opening a new tab. Please allow popups for SteamGifts.',\n        timeout: isRu ? 'Время ожидания истекло. Если вкладка зависла на Cloudflare, пройдите проверку вручную.' : 'Timeout waiting for SteamDB. If blocked by Cloudflare, solve captcha manually.',\n        noRestrictions: isRu ? 'Ограничений не найдено. Пакет доступен по всему миру.' : 'No restrictions found. Package is available worldwide.',\n        partialWarning: (count, missingList) => isRu\n            ? `Частично импортировано (выбрано: ${count}). Внимание! Отсутствуют на SteamGifts: ${missingList}`\n            : `Partially imported (selected: ${count}). Warning! Missing on SteamGifts: ${missingList}`,\n        success: (count) => isRu\n            ? `Успешно импортировано! Выбрано стран: ${count}`\n            : `Successfully imported! Countries selected: ${count}`,\n    };\n\n    if (location.hostname === 'www.steamgifts.com') {\n        runSteamGifts();\n    } else if (location.hostname === 'steamdb.info') {\n        runSteamDB();\n    }\n\n    // --- ЛОГИКА ДЛЯ СТРАНИЦЫ STEAMGIFTS ---\n    function runSteamGifts() {\n        let regionRow = null;\n        const headingTextElements = document.querySelectorAll('.form__heading__text');\n\n        headingTextElements.forEach(el => {\n            if (el.textContent.trim() === 'Region Restricted') {\n                regionRow = el.closest('.form__row');\n            }\n        });\n\n        if (!regionRow) return;\n\n        const container = document.createElement('div');\n        container.id = 'sg-steamdb-addon-container';\n        container.style.display = 'none';\n        container.style.alignItems = 'center';\n        container.style.marginLeft = '20px';\n        container.style.gap = '8px';\n\n        container.innerHTML = `\n            <span style=\"font-size: 12px; font-weight: normal; color: #555;\">${i18n.subIdLabel}</span>\n            <input type=\"text\" id=\"sg-subid-input\" placeholder=\"${i18n.placeholder}\" style=\"width: 100px; padding: 4px 6px; font-size: 12px; border: 1px solid #ccc; border-radius: 4px;\">\n            <button type=\"button\" id=\"sg-subid-btn\" style=\"padding: 4px 10px; font-size: 12px; background: #4b729f; color: #fff; border: none; border-radius: 4px; cursor: pointer;\">${i18n.applyBtn}</button>\n            <span id=\"sg-subid-status\" style=\"font-size: 11px; color: #666; font-weight: bold;\"></span>\n        `;\n\n        const heading = regionRow.querySelector('.form__heading');\n        if (heading) {\n            heading.appendChild(container);\n        }\n\n        const inputEl = document.getElementById('sg-subid-input');\n        const btnEl = document.getElementById('sg-subid-btn');\n        const statusEl = document.getElementById('sg-subid-status');\n\n        const yesCheckbox = regionRow.querySelector('div[data-checkbox-value=\"1\"]');\n        const noCheckbox = regionRow.querySelector('div[data-checkbox-value=\"0\"]');\n\n        function updateUiVisibility() {\n            if (yesCheckbox && yesCheckbox.classList.contains('is-selected')) {\n                container.style.setProperty('display', 'inline-flex', 'important');\n            } else {\n                container.style.setProperty('display', 'none', 'important');\n            }\n        }\n\n        if (yesCheckbox) yesCheckbox.addEventListener('click', () => setTimeout(updateUiVisibility, 50));\n        if (noCheckbox) noCheckbox.addEventListener('click', () => setTimeout(updateUiVisibility, 50));\n\n        setTimeout(updateUiVisibility, 200);\n\n        function setStatus(text, color) {\n            statusEl.textContent = text;\n            statusEl.style.color = color || '#666';\n        }\n\n        btnEl.addEventListener('click', () => {\n            const subId = inputEl.value.trim();\n            if (!subId || isNaN(subId)) {\n                setStatus(i18n.enterValidSubId, 'red');\n                return;\n            }\n\n            setStatus(i18n.openingTab, 'orange');\n\n            GM_setValue('parsed_sub_data', null);\n            GM_setValue('requested_sub', subId);\n\n            const steamDbUrl = `https://steamdb.info/sub/${subId}/?sg_sync=1`;\n            const newTab = window.open(steamDbUrl, '_blank');\n\n            if (!newTab) {\n                setStatus(i18n.popupBlocked, 'red');\n                return;\n            }\n\n            let attempts = 0;\n            const maxAttempts = 60;\n            const interval = setInterval(() => {\n                attempts++;\n                const result = GM_getValue('parsed_sub_data');\n\n                if (result && result.subId === subId) {\n                    clearInterval(interval);\n                    applyRestrictions(result);\n                } else if (attempts >= maxAttempts) {\n                    clearInterval(interval);\n                    setStatus(i18n.timeout, 'red');\n                }\n            }, 500);\n        });\n\n        function applyRestrictions(data) {\n            if (data.type === 'none') {\n                setStatus(i18n.noRestrictions, 'green');\n                if (noCheckbox && !noCheckbox.classList.contains('is-selected')) {\n                    noCheckbox.click();\n                    setTimeout(updateUiVisibility, 50);\n                }\n                return;\n            }\n\n            if (yesCheckbox && !yesCheckbox.classList.contains('is-selected')) {\n                yesCheckbox.click();\n            }\n\n            const sgItems = regionRow.querySelectorAll('.form_list_item');\n            const allSgCodes = [];\n\n            sgItems.forEach(item => {\n                const dataName = item.getAttribute('data-name') || '';\n                const code = dataName.split(' ').pop().toUpperCase();\n                if (code) {\n                    allSgCodes.push(code);\n                }\n            });\n\n            // Находим расхождения (страны из SteamDB, отсутствующие на SteamGifts)\n            const missingCountries = data.countries.filter(item => !allSgCodes.includes(item.code));\n\n            // Преобразуем данные в плоский массив кодов для выбора на странице\n            const dbCodes = data.countries.map(item => item.code);\n\n            let targetCodes = [];\n            if (data.type === 'only') {\n                targetCodes = dbCodes;\n            } else if (data.type === 'not') {\n                targetCodes = allSgCodes.filter(code => !dbCodes.includes(code));\n            }\n\n            // Изменяем чекбоксы\n            sgItems.forEach(item => {\n                const dataName = item.getAttribute('data-name') || '';\n                const code = dataName.split(' ').pop().toUpperCase();\n                const isSelected = item.classList.contains('is-selected');\n                const shouldBeSelected = targetCodes.includes(code);\n\n                if (isSelected !== shouldBeSelected) {\n                    item.click();\n                }\n            });\n\n            // Считаем количество РЕАЛЬНО отмеченных галочек на странице\n            const actualSelectedCount = regionRow.querySelectorAll('.form_list_item.is-selected').length;\n\n            if (missingCountries.length > 0) {\n                const missingTextList = missingCountries.map(item => `${item.name} (${item.code})`).join(', ');\n                setStatus(i18n.partialWarning(actualSelectedCount, missingTextList), '#d97706');\n            } else {\n                setStatus(i18n.success(actualSelectedCount), 'green');\n            }\n        }\n    }\n\n    // --- ЛОГИКА ДЛЯ ВРЕМЕННОЙ ВКЛАДКИ STEAMDB ---\n    function runSteamDB() {\n        if (!location.search.includes('sg_sync=1')) {\n            return;\n        }\n\n        const match = location.pathname.match(/\\/sub\\/(\\d+)/);\n        if (!match) return;\n        const subId = match[1];\n\n        const requestedSub = GM_getValue('requested_sub');\n        if (requestedSub !== subId) return;\n\n        const isPageLoaded = document.getElementById('info') || document.querySelector('.pageheader');\n        if (!isPageLoaded) return;\n\n        const restrictionPanel = document.querySelector('.panel-error');\n        let type = 'none';\n        const countries = []; // Содержит объекты вида { code: 'FR', name: 'France' }\n\n        if (restrictionPanel) {\n            const headingSpan = restrictionPanel.querySelector('.panel-heading span');\n            if (headingSpan) {\n                const text = headingSpan.textContent.trim();\n                if (text.includes('can only be activated')) {\n                    type = 'only';\n                } else if (text.includes('can NOT be activated')) {\n                    type = 'not';\n                }\n            }\n\n            // Парсим список стран (коды + текстовые названия)\n            const listItems = restrictionPanel.querySelectorAll('.country-list-grid li');\n            listItems.forEach(li => {\n                const img = li.querySelector('img');\n                if (!img) return;\n\n                const src = img.getAttribute('src') || '';\n                const m = src.match(/\\/country\\/([a-z0-9]+)\\.svg/i);\n                if (m) {\n                    const code = m[1].toUpperCase();\n                    const span = li.querySelector('span');\n                    let name = span ? span.textContent : li.textContent;\n                    name = name.replace(/\\s+/g, ' ').trim();\n\n                    countries.push({\n                        code: code,\n                        name: name\n                    });\n                }\n            });\n        }\n\n        GM_setValue('parsed_sub_data', {\n            subId: subId,\n            type: type,\n            countries: countries,\n            timestamp: Date.now()\n        });\n\n        window.close();\n    }\n})();\n","steamgifts-unlucky-7-winner-stats-copy.user.js":"// ==UserScript==\n// @name         SteamGifts - Unlucky-7 Winner Stats & Copy\n// @name:ru      SteamGifts - Статистика победителей Unlucky-7 и копирование\n// @namespace    https://greasyfork.org/users/1522624-basimovif-ai\n// @version      1.4.1\n// @description  Displays interactive winner stats for the Unlucky-7 group on giveaway pages and allows copying formatted data to the clipboard.\n// @description:ru Отображает интерактивную статистику победителей группы Unlucky-7 на страницах раздач и позволяет копировать отформатированные данные в буфер обмена.\n// @author       basimovif-ai\n// @license      MIT\n// @homepageURL  https://github.com/BasimovIF-AI/steamgifts-userscripts\n// @supportURL   https://github.com/BasimovIF-AI/steamgifts-userscripts/issues\n// @match        https://www.steamgifts.com/giveaway/*/winners\n// @grant        none\n// ==/UserScript==\n\n(function() {\n    'use strict';\n\n    const isRu = (navigator.language || '').toLowerCase().startsWith('ru');\n    const i18n = {\n        formulaTitle: isRu ? 'Нажмите для полной формулы расчета' : 'Click to toggle calculation formula',\n        copyTitle: isRu ? 'Скопировать информацию о победителе' : 'Copy winner info to clipboard',\n        errorLog: isRu ? 'Ошибка при сборе данных для пользователя ' : 'Error fetching data for user ',\n    };\n\n    // 1. Проверяем наличие группы \"Unlucky-7\" на странице раздачи\n    const groupLink = Array.from(document.querySelectorAll('a.featured__column--group'))\n        .find(el => el.getAttribute('title') === 'Unlucky-7' || el.textContent.trim() === 'Unlucky-7');\n\n    if (!groupLink) {\n        return; // Если группа не найдена, завершаем работу\n    }\n\n    const groupSearchBaseUrl = 'https://www.steamgifts.com/group/WWF2y/unlucky-7/users/search?q=';\n    const gaUrl = window.location.origin + window.location.pathname.replace(/\\/winners$/, '');\n\n    // Вспомогательная функция для получения порядкового суффикса числительных (1st, 2nd, 3rd, 4th...)\n    const getOrdinalSuffix = (num) => {\n        const j = num % 10, k = num % 100;\n        if (j === 1 && k !== 11) return num + \"st\";\n        if (j === 2 && k !== 12) return num + \"nd\";\n        if (j === 3 && k !== 13) return num + \"rd\";\n        return num + \"th\";\n    };\n\n    // Вспомогательные функции парсинга\n    const parseSentRec = (text) => {\n        const cleaned = text.replace(/,/g, '');\n        const m = cleaned.match(/([\\d.]+)\\s*\\(\\$([\\d.]+)\\)/);\n        return m ? [parseFloat(m[1]), parseFloat(m[2])] : [0, 0];\n    };\n\n    const parseDiff = (text) => {\n        return parseFloat(text.replace(/[^0-9.-]/g, ''));\n    };\n\n    // 2. Находим всех победителей в таблице\n    const winnerRows = document.querySelectorAll('.table__rows .table__row-outer-wrap');\n\n    winnerRows.forEach(row => {\n        const userLink = row.querySelector('.table__column__heading a');\n        if (!userLink) return;\n\n        const username = userLink.textContent.trim();\n        const parentNode = userLink.parentNode;\n\n        // Создаем индикатор загрузки\n        const loader = document.createElement('i');\n        loader.className = 'fa fa-refresh fa-spin';\n        loader.style.marginLeft = '8px';\n        loader.style.color = '#7f8c8d';\n        loader.style.fontSize = '12px';\n        parentNode.appendChild(loader);\n\n        const groupSearchUrl = groupSearchBaseUrl + encodeURIComponent(username);\n        const profileUrl = `https://www.steamgifts.com/user/${username}`;\n\n        // Выполняем запросы к группе и к профилю параллельно\n        Promise.all([\n            fetch(groupSearchUrl).then(r => r.text()),\n            fetch(profileUrl).then(r => r.text())\n        ])\n        .then(([groupHtml, profileHtml]) => {\n            loader.remove();\n\n            const parser = new DOMParser();\n\n            // --- Парсинг данных из группы ---\n            const groupDoc = parser.parseFromString(groupHtml, 'text/html');\n            const memberRows = groupDoc.querySelectorAll('.table__rows .table__row-outer-wrap');\n            let userData = null;\n\n            for (const memberRow of memberRows) {\n                const nameEl = memberRow.querySelector('.table__column__heading');\n                if (nameEl && nameEl.textContent.trim().toLowerCase() === username.toLowerCase()) {\n                    const cols = memberRow.querySelectorAll('.table__column--width-small.text-center');\n                    if (cols.length >= 4) {\n                        userData = {\n                            sentText: cols[0].textContent.trim(),\n                            recText: cols[1].textContent.trim(),\n                            siteGiftDiffStr: cols[2].textContent.trim(),\n                            siteValueDiffStr: cols[3].textContent.trim()\n                        };\n                        break;\n                    }\n                }\n            }\n\n            if (!userData) return;\n\n            // --- Парсинг \"Gifts Won\" из профиля ---\n            const profileDoc = parser.parseFromString(profileHtml, 'text/html');\n            const profileRows = profileDoc.querySelectorAll('.featured__table__row');\n            let giftsWon = 0;\n\n            for (const pRow of profileRows) {\n                const left = pRow.querySelector('.featured__table__row__left');\n                if (left && left.textContent.trim() === 'Gifts Won') {\n                    const right = pRow.querySelector('.featured__table__row__right a');\n                    if (right) {\n                        giftsWon = parseInt(right.textContent.replace(/,/g, ''), 10);\n                    }\n                    break;\n                }\n            }\n\n            // Вычисления и независимая валидация для каждой разницы\n            const [sentCount, sentValue] = parseSentRec(userData.sentText);\n            const [recCount, recValue] = parseSentRec(userData.recText);\n            const siteGiftDiff = parseDiff(userData.siteGiftDiffStr);\n            const siteValueDiff = parseDiff(userData.siteValueDiffStr);\n\n            const calculatedGiftDiff = sentCount - recCount;\n            const calculatedValueDiff = sentValue - recValue;\n\n            const isGiftMatch = Math.abs(calculatedGiftDiff - siteGiftDiff) < 0.05;\n            const isValueMatch = Math.abs(calculatedValueDiff - siteValueDiff) < 0.05;\n\n            const giftColor = isGiftMatch ? '#2e7d32' : '#c62828';\n            const valueColor = isValueMatch ? '#2e7d32' : '#c62828';\n\n            // Отрисовка интерактивного элемента статистики\n            const statsContainer = document.createElement('span');\n            statsContainer.style.cursor = 'pointer';\n            statsContainer.style.marginLeft = '8px';\n            statsContainer.style.fontSize = '12px';\n            statsContainer.style.fontWeight = 'bold';\n            statsContainer.style.userSelect = 'none';\n            statsContainer.style.color = '#7f8c8d';\n            statsContainer.style.transition = 'opacity 0.15s ease';\n            statsContainer.title = i18n.formulaTitle;\n\n            // Генерация DOM структуры в зависимости от состояния свертки\n            const renderStats = (expanded) => {\n                statsContainer.innerHTML = '';\n\n                // Открывающая скобка\n                const openBracket = document.createElement('span');\n                openBracket.textContent = '(';\n                statsContainer.appendChild(openBracket);\n\n                // Блок разницы подарков\n                if (expanded) {\n                    const formula = document.createElement('span');\n                    formula.textContent = `${sentCount}-${recCount}=`;\n                    statsContainer.appendChild(formula);\n                }\n                const giftResult = document.createElement('span');\n                giftResult.textContent = userData.siteGiftDiffStr;\n                giftResult.style.color = giftColor;\n                statsContainer.appendChild(giftResult);\n\n                // Разделитель\n                const separator = document.createElement('span');\n                separator.textContent = '; ';\n                statsContainer.appendChild(separator);\n\n                // Блок разницы стоимости\n                if (expanded) {\n                    const formula = document.createElement('span');\n                    formula.textContent = `$${sentValue}-$${recValue}=`;\n                    statsContainer.appendChild(formula);\n                }\n                const valueResult = document.createElement('span');\n                valueResult.textContent = userData.siteValueDiffStr;\n                valueResult.style.color = valueColor;\n                statsContainer.appendChild(valueResult);\n\n                // Закрывающая скобка\n                const closeBracket = document.createElement('span');\n                closeBracket.textContent = ')';\n                statsContainer.appendChild(closeBracket);\n\n                // Количество побед в развернутом режиме\n                if (expanded) {\n                    const winsSpan = document.createElement('span');\n                    winsSpan.textContent = ` ${giftsWon}`;\n                    statsContainer.appendChild(winsSpan);\n                }\n            };\n\n            let isExpanded = false;\n            renderStats(isExpanded);\n\n            statsContainer.addEventListener('mouseenter', () => { statsContainer.style.opacity = '0.7'; });\n            statsContainer.addEventListener('mouseleave', () => { statsContainer.style.opacity = '1'; });\n\n            statsContainer.addEventListener('click', (e) => {\n                e.preventDefault();\n                isExpanded = !isExpanded;\n                renderStats(isExpanded);\n            });\n\n            parentNode.appendChild(statsContainer);\n\n            // --- Создание кнопки копирования ---\n            const badgeText = (giftsWon <= 8)\n                ? `${getOrdinalSuffix(giftsWon)} win`\n                : `Gifter, ${userData.siteGiftDiffStr}`;\n\n            const clipboardText = `GA: ${gaUrl}\\nWinner: ${profileUrl} (${badgeText})`;\n\n            const copyBtn = document.createElement('i');\n            copyBtn.className = 'fa fa-clipboard';\n            copyBtn.style.marginLeft = '8px';\n            copyBtn.style.cursor = 'pointer';\n            copyBtn.style.color = '#7f8c8d';\n            copyBtn.style.fontSize = '12px';\n            copyBtn.style.transition = 'color 0.15s ease';\n            copyBtn.title = i18n.copyTitle;\n\n            copyBtn.addEventListener('mouseenter', () => { copyBtn.style.color = '#333'; });\n            copyBtn.addEventListener('mouseleave', () => { copyBtn.style.color = '#7f8c8d'; });\n\n            copyBtn.addEventListener('click', (e) => {\n                e.preventDefault();\n                navigator.clipboard.writeText(clipboardText).then(() => {\n                    copyBtn.className = 'fa fa-check';\n                    copyBtn.style.color = '#2e7d32';\n                    setTimeout(() => {\n                        copyBtn.className = 'fa fa-clipboard';\n                        copyBtn.style.color = '#7f8c8d';\n                    }, 1500);\n                }).catch(err => {\n                    console.error('SteamGifts Unlucky-7: clipboard error:', err);\n                });\n            });\n\n            parentNode.appendChild(copyBtn);\n        })\n        .catch(err => {\n            loader.remove();\n            console.error(i18n.errorLog + username, err);\n        });\n    });\n})();\n"};
    const embeddedDescs = {"steamgifts-chance-per-point.user.js":"### 🎯 About / О скрипте\n**EN**: Calculates your **exact win probability per single entry point in basis points (‱)** and adds a dynamic filter to hide low-yield giveaways on SteamGifts.\n**RU**: Рассчитывает **точный шанс на победу за одно затраченное очко в базисных пунктах (‱)** и позволяет скрывать невыгодные раздачи на странице участий SteamGifts.\n\n---\n\n### 🌟 Key Features / Возможности\n\n* **🧮 Smart Calculation / Точный расчёт шанса**:\n  * **Formula / Формула**: `(Copies / (Entries * Points)) * 10,000‱`\n  * **Basis Points (‱)**: Instead of confusing numbers like `0.0012%`, values are shown as clean numbers like `12.50‱` or `2.40‱` (`1‱ = 0.01% = 0.0001`).\n  * **Dedicated Column**: Adds a styled column `Шанс/Очко (‱)` / `Chance/Pt (‱)` to the entered giveaways table.\n* **🔍 Dynamic Threshold Filter / Фильтр раздач**:\n  * Input your threshold (e.g. `1.00‱`) and click **Filter** to instantly hide giveaways with lower winning chances.\n  * **Reset** button restores all rows in 1 click.\n  * Automatic observation via `MutationObserver` for continuous scrolling/pagination.\n* **🌐 Bilingual UI / Двуязычный интерфейс**:\n  * UI buttons, tooltips, and column headers automatically adapt to browser language (`RU` / `EN`).\n\n---\n\n### 💻 Source Code & Support\n* **GitHub Repository**: [https://github.com/BasimovIF-AI/steamgifts-userscripts](https://github.com/BasimovIF-AI/steamgifts-userscripts)\n* **License**: [MIT License](https://opensource.org/licenses/MIT)","steamgifts-group-stats-checker.user.js":"### 👥 About / О скрипте\n**EN**: Displays interactive group statistics for the user on giveaway pages and automatically fills courteous creator thank-you comments.\n**RU**: Отображает интерактивные кнопки статистики пользователя в группах раздачи и автоматически заполняет вежливую благодарность создателю раздачи.\n\n---\n\n### 🌟 Key Features / Возможности\n\n* **📊 Group Stat Buttons / Проверка баланса в группах**:\n  * Automatically detects all groups linked to the giveaway and places stat buttons next to group indicators.\n  * Fetches gifts sent vs received and dollar value difference.\n  * **Color Validation**: 🟢 Green for exact match with site data, 🔴 Red for discrepancies.\n* **🔍 Clickable Math Breakdown / Раскрытие формулы по клику**:\n  * **Collapsed**: Summary `(+5; +$82.50)`.\n  * **Expanded (on click)**: Exact math formula `(12-7=+5; $150-$67.5=+$82.50)` and total `Gifts Won` count!\n* **✍️ Creator Thank-You Autofill / Авто-комментарий автору**:\n  * Automatically fills empty description field with: `Thanks a lot [CreatorName]!`.\n\n---\n\n### 💻 Source Code & Support\n* **GitHub Repository**: [https://github.com/BasimovIF-AI/steamgifts-userscripts](https://github.com/BasimovIF-AI/steamgifts-userscripts)\n* **License**: [MIT License](https://opensource.org/licenses/MIT)","steamgifts-region-auto-selector.user.js":"### 🌍 About / О скрипте\n**EN**: Bypasses Cloudflare by opening SteamDB in a brief temporary tab and auto-selects restricted countries when creating SteamGifts giveaways.\n**RU**: Обходит Cloudflare открытием временной вкладки SteamDB и автоматически отмечает региональные ограничения при создании раздачи на SteamGifts.\n\n---\n\n### 🌟 Key Features / Возможности\n\n* **🛡️ Seamless Cloudflare Bypass / Обход Cloudflare**:\n  * Opens a temporary tab to let the browser natively pass Cloudflare, parses package restrictions, and closes automatically.\n* **⚡ 1-Click Import by SubID / Импорт по SubID в 1 клик**:\n  * Enter Steam package SubID (e.g. `828967`) and click **Apply**. All restricted/allowed countries are selected automatically in the SteamGifts form!\n* **⚠️ Discrepancy Warnings / Сверка стран**:\n  * Warns you if any country codes from SteamDB are missing from SteamGifts database.\n\n---\n\n### 💻 Source Code & Support\n* **GitHub Repository**: [https://github.com/BasimovIF-AI/steamgifts-userscripts](https://github.com/BasimovIF-AI/steamgifts-userscripts)\n* **License**: [MIT License](https://opensource.org/licenses/MIT)","steamgifts-unlucky-7-winner-stats-copy.user.js":"### 🎲 About / О скрипте\n**EN**: Displays interactive winner stats for the Unlucky-7 group on giveaway pages and allows 1-click formatted clipboard copying.\n**RU**: Отображает интерактивную статистику победителей группы Unlucky-7 на страницах раздач и позволяет копировать отформатированные данные в буфер обмена.\n\n---\n\n### 🌟 Key Features / Возможности\n\n* **🎯 Targeted Activation / Точечная активация**:\n  * Runs exclusively on giveaway winner pages (`.../giveaway/*/winners`) for the `Unlucky-7` group.\n* **📊 Interactive Winner Stats / Статистика победителя**:\n  * Displays gift & value difference with clickable calculation breakdown.\n  * Color-coded validation: 🟢 Green for match, 🔴 Red for discrepancy.\n* **📋 1-Click Copy / Копирование для отчётности**:\n  * Copies formatted string tailored for group accounting:\n    * `<= 8 wins`: `GA: <url>\\nWinner: <user> (Xth win)`\n    * `> 8 wins`: `GA: <url>\\nWinner: <user> (Gifter, +X)`\n\n---\n\n### 💻 Source Code & Support\n* **GitHub Repository**: [https://github.com/BasimovIF-AI/steamgifts-userscripts](https://github.com/BasimovIF-AI/steamgifts-userscripts)\n* **License**: [MIT License](https://opensource.org/licenses/MIT)"};
    const embeddedChangelogs = {"steamgifts-unlucky-7-winner-stats-copy.user.js":"v1.4.1: Added Russian localization (@name:ru, @description:ru) for GreasyFork catalog","steamgifts-chance-per-point.user.js":"v7.0.0: Added Russian localization and basis point formatting"};

    const scriptCode = embeddedCodes[fileName] || '';
    const scriptDesc = embeddedDescs[fileName] || '';
    const changelogText = embeddedChangelogs[fileName] || 'Update description and localization';

    const isRu = (navigator.language || '').toLowerCase().startsWith('ru');
    const i18n = {
        title: '🤖 GreasyFork Auto-Publisher v2.0',
        populating: isRu ? `Заполнение формы для ${fileName}...` : `Populating form for ${fileName}...`,
        ready: isRu ? 'Все поля (код, CodeMirror, Markdown, описание) успешно заполнены!' : 'All fields populated!',
        submittingIn: (s) => isRu ? `Авто-отправка через: ${s} сек...` : `Auto-submitting in: ${s}s...`,
        submitting: isRu ? '🚀 Отправка формы на сервер GreasyFork...' : '🚀 Submitting to GreasyFork...',
        nowBtn: isRu ? '🚀 Отправить сейчас' : '🚀 Submit Now',
        pauseBtn: isRu ? '⏸️ Пауза / Проверить' : '⏸️ Pause',
        paused: isRu ? 'Авто-отправка на паузе. Проверьте форму и нажмите кнопку отправки вручную.' : 'Paused. You can submit manually.'
    };

    // Создание плавающего UI-баннера
    const banner = document.createElement('div');
    banner.id = 'gf-auto-publisher-banner';
    Object.assign(banner.style, {
        position: 'fixed',
        top: '20px',
        right: '20px',
        zIndex: '9999999',
        backgroundColor: '#0f172a',
        color: '#f8fafc',
        padding: '16px 20px',
        borderRadius: '10px',
        boxShadow: '0 10px 30px rgba(0,0,0,0.6)',
        border: '2px solid #38bdf8',
        fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
        maxWidth: '420px',
        fontSize: '14px',
        lineHeight: '1.5'
    });

    banner.innerHTML = `
        <div style="font-weight: 700; color: #38bdf8; font-size: 15px; margin-bottom: 6px;">${i18n.title}</div>
        <div id="gf-ap-status" style="color: #cbd5e1; margin-bottom: 12px;">${i18n.populating}</div>
        <div id="gf-ap-actions" style="display: flex; gap: 8px;">
            <button id="gf-ap-submit-now" style="background: #2563eb; color: white; border: none; padding: 7px 14px; border-radius: 6px; cursor: pointer; font-size: 13px; font-weight: 600;">${i18n.nowBtn}</button>
            <button id="gf-ap-pause" style="background: #ef4444; color: white; border: none; padding: 7px 14px; border-radius: 6px; cursor: pointer; font-size: 13px; font-weight: 600;">${i18n.pauseBtn}</button>
        </div>
    `;
    document.body.appendChild(banner);

    const statusEl = document.getElementById('gf-ap-status');
    const actionsEl = document.getElementById('gf-ap-actions');
    const submitNowBtn = document.getElementById('gf-ap-submit-now');
    const pauseBtn = document.getElementById('gf-ap-pause');

    let countdownTimer = null;

    // Внедрение кода в контекст страницы для взаимодействия с CodeMirror и формой
    function injectPageScript(fn, ...args) {
        const script = document.createElement('script');
        script.textContent = '(' + fn.toString() + ')(' + args.map(a => JSON.stringify(a)).join(',') + ');';
        document.documentElement.appendChild(script);
        script.remove();
    }

    // Функция, исполняемая в нативном контексте страницы GreasyFork
    function pageContextFiller(code, desc, changelog, isEditDesc) {
        // 1. Поле кода и CodeMirror
        const codeArea = document.querySelector('textarea#script_version_code, textarea[name="script_version[code]"]');
        if (codeArea && code && !isEditDesc) {
            codeArea.value = code;
            codeArea.dispatchEvent(new Event('input', { bubbles: true }));
            codeArea.dispatchEvent(new Event('change', { bubbles: true }));

            // Проверяем все элементы CodeMirror
            const cmEls = document.querySelectorAll('.CodeMirror');
            cmEls.forEach(cmEl => {
                if (cmEl.CodeMirror) {
                    cmEl.CodeMirror.setValue(code);
                    cmEl.CodeMirror.save();
                }
            });
        }

        // 2. Переключение разметки на Markdown
        const radios = Array.from(document.querySelectorAll('input[type="radio"]'));
        const mdRadio = radios.find(r => r.value === 'markdown' || (r.id && r.id.toLowerCase().includes('markdown')));
        if (mdRadio) {
            mdRadio.checked = true;
            mdRadio.click();
            mdRadio.dispatchEvent(new Event('change', { bubbles: true }));
        }

        const selects = Array.from(document.querySelectorAll('select'));
        for (const sel of selects) {
            if (sel.name && sel.name.includes('markup')) {
                sel.value = 'markdown';
                sel.dispatchEvent(new Event('change', { bubbles: true }));
            }
        }

        // 3. Поле дополнительной информации / описания
        const allTextareas = Array.from(document.querySelectorAll('textarea'));
        const descArea = allTextareas.find(t => t !== codeArea && (t.name?.includes('additional_info') || t.id?.includes('additional_info'))) ||
                         allTextareas.find(t => t !== codeArea);

        if (descArea && desc) {
            descArea.value = desc;
            descArea.dispatchEvent(new Event('input', { bubbles: true }));
            descArea.dispatchEvent(new Event('change', { bubbles: true }));

            const cmDesc = descArea.nextElementSibling;
            if (cmDesc && cmDesc.CodeMirror) {
                cmDesc.CodeMirror.setValue(desc);
                cmDesc.CodeMirror.save();
            }
        }

        // 4. Поле Changelog
        const clInput = document.querySelector('input[name*="changelog"], textarea[name*="changelog"], input#script_version_changelog');
        if (clInput && changelog) {
            clInput.value = changelog;
            clInput.dispatchEvent(new Event('input', { bubbles: true }));
            clInput.dispatchEvent(new Event('change', { bubbles: true }));
        }

        // 5. Авто-отметка чекбокса дубликата кода
        const dupCheck = document.querySelector('input[type="checkbox"][name*="allow_code_previously_posted"], input[type="checkbox"][name*="previously_posted"], input[type="checkbox"][name*="allow_code"], input[type="checkbox"][name*="version_check_override"]');
        if (dupCheck && !dupCheck.checked) {
            dupCheck.checked = true;
            dupCheck.dispatchEvent(new Event('change', { bubbles: true }));
        }
    }

    function pageContextSubmit(isNewPublish, pubName) {
        if (isNewPublish && pubName) {
            sessionStorage.setItem('gf_pending_desc', pubName);
        }

        // Синхронизация CodeMirror перед отправкой
        document.querySelectorAll('.CodeMirror').forEach(cm => {
            if (cm.CodeMirror) cm.CodeMirror.save();
        });

        // Повторная проверка чекбокса
        const dupCheck = document.querySelector('input[type="checkbox"][name*="allow_code_previously_posted"], input[type="checkbox"][name*="previously_posted"], input[type="checkbox"][name*="allow_code"], input[type="checkbox"][name*="version_check_override"]');
        if (dupCheck && !dupCheck.checked) {
            dupCheck.checked = true;
            dupCheck.dispatchEvent(new Event('change', { bubbles: true }));
        }

        const submitBtn = document.querySelector('input[type="submit"][name="commit"], input[type="submit"], button[type="submit"]');
        if (submitBtn) {
            submitBtn.click();
        } else {
            const form = document.querySelector('form');
            if (form) form.submit();
        }
    }

    function doSubmit() {
        if (countdownTimer) clearInterval(countdownTimer);
        statusEl.innerHTML = `<span style="color: #38bdf8;">${i18n.submitting}</span>`;
        actionsEl.style.display = 'none';

        injectPageScript(pageContextSubmit, !!publishFile, publishFile || '');
    }

    pauseBtn.addEventListener('click', () => {
        if (countdownTimer) clearInterval(countdownTimer);
        statusEl.innerHTML = `<span style="color: #fbbf24;">${i18n.paused}</span>`;
        pauseBtn.style.display = 'none';
        banner.style.borderColor = '#fbbf24';
    });

    submitNowBtn.addEventListener('click', () => {
        doSubmit();
    });

    // Запуск заполнения
    setTimeout(() => {
        injectPageScript(pageContextFiller, scriptCode, scriptDesc, changelogText, !!editDescFile);

        statusEl.innerHTML = `<span style="color: #4ade80;">${i18n.ready}</span><br><b>${i18n.submittingIn(5)}</b>`;
        banner.style.borderColor = '#4ade80';

        let sec = 5;
        countdownTimer = setInterval(() => {
            sec--;
            if (sec > 0) {
                statusEl.innerHTML = `<span style="color: #4ade80;">${i18n.ready}</span><br><b>${i18n.submittingIn(sec)}</b>`;
            } else {
                doSubmit();
            }
        }, 1000);
    }, 600);

})();
